---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import {
  Section,
  SectionContainer,
  SectionDescription,
  SectionTitle,
} from "@/components/ui/section"

type Props = HTMLAttributes<"section"> & {
  title: string
  description: string
  buttons?: {
    label: string
    href: string
    variant?: "default" | "outline" | "secondary" | "ghost"
  }[]
  features: {
    title: string
    description: string
    icon: string
  }[]
}

const {
  class: className,
  title,
  description,
  buttons,
  features,
  ...props
} = Astro.props
---

<Section variant="floating" class={cn("", className)} {...props}>
  <SectionContainer class="items-center gap-6 text-center">
    <div class="flex max-w-2xl flex-col items-center gap-4">
      <SectionTitle>
        {title}
      </SectionTitle>
      <SectionDescription class="max-w-2xl">
        {description}
      </SectionDescription>
    </div>
    {
      buttons?.length && (
        <div class="flex flex-wrap justify-center gap-3">
          {buttons.map(({ href, label, ...button }, index) => (
            <Button
              as="a"
              href={href}
              variant={button.variant ?? (index === 0 ? "default" : "outline")}
              {...button}
            >
              {label}
            </Button>
          ))}
        </div>
      )
    }
  </SectionContainer>
  <SectionContainer>
    <div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
      {
        features.map((feature) => (
          <div class="group/feature flex flex-col items-center gap-4 text-center">
            <div class="bg-primary/5 text-primary border-primary/20 flex size-12 items-center justify-center rounded-xl border">
              <Icon name={feature.icon} class="size-5" />
            </div>
            <h3 class="text-foreground text-base font-medium text-balance">
              {feature.title}
            </h3>
            <p class="text-muted-foreground text-sm leading-relaxed text-balance">
              {feature.description}
            </p>
          </div>
        ))
      }
    </div>
  </SectionContainer>
</Section>
